<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Facades\DB;
class CustomerEngagementController extends Controller {
 public function wishlist(Request $r,string $category,string $product):RedirectResponse{$id=$r->attributes->get('customer')->id;$existing=DB::table('wishlists')->where(['customer_id'=>$id,'category_key'=>$category,'product_handle'=>$product])->first();if($existing)DB::table('wishlists')->where('id',$existing->id)->delete();else DB::table('wishlists')->insert(['customer_id'=>$id,'category_key'=>$category,'product_handle'=>$product,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success',$existing?'Von der Wunschliste entfernt.':'Zur Wunschliste hinzugefügt.');}
 public function notify(Request $r,int $id):RedirectResponse{DB::table('wishlists')->where('id',$id)->where('customer_id',$r->attributes->get('customer')->id)->update(['notify_back_in_stock'=>$r->boolean('notify'),'updated_at'=>now()]);return back()->with('success','Benachrichtigung gespeichert.');}
 public function review(Request $r,string $category,string $product):RedirectResponse{$customer=$r->attributes->get('customer');$d=$r->validate(['rating'=>['required','integer','between:1,5'],'comment'=>['required','string','min:10','max:1500']]);$bought=DB::table('checkout_requests')->where(fn($q)=>$q->where('customer_id',$customer->id)->orWhere('email',$customer->email))->where('cart','like','%"product_handle":"'.$product.'"%')->exists();abort_unless($bought,403,'Nur Käufer dieses Produkts können eine Bewertung abgeben.');DB::table('product_reviews')->updateOrInsert(['customer_id'=>$customer->id,'category_key'=>$category,'product_handle'=>$product],[...$d,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Danke! Deine Bewertung wird geprüft.');}
}
